import kotlin.math.roundToInt

/**
 * A simplified rendition of the Key Levels range bar from the Design mockups -- a horizontal track
 * spanning `axisLow`..`axisHigh`, a bordered "value area" band, a fair-value tick, support/
 * resistance ticks, and a labeled marker for the current price. Not a pixel-match of the mockup
 * (which has finer gradient detail); this keeps to the same Canvas-drawing technique
 * `PutCallHorizontalBar` already uses elsewhere (`drawRoundRect` + `drawLine` ticks) rather than a
 * new drawing approach. Support/resistance are signal-colored (bullish green / bearish red) as the
 * floor/ceiling read they are; the fair-value tick and axis labels are plain `onSurface` text color
 * rather than a signal color, since a fair-value read and a bare price range aren't a bullish/
 * bearish call the way a support or resistance level is.
 *
 * 💡 Positions are ranked, not proportional to the actual dollar values -- `axisLow`, `valueAreaLow`,
 * `fairValueAnchor`, `valueAreaHigh`, `support`, `currentPrice`, `resistance`, and `axisHigh` are
 * sorted, de-duplicated, and spread evenly across the track by that sort order alone. A literal
 * dollar-proportional layout put resistance (this bar's own upper axis bound) flush against the
 * track's right edge with no visual room of its own, while price and support could end up crowded
 * together with a big empty gap after them, purely as an accident of how far apart their dollar
 * values happened to be. Even, rank-based spacing means every marker always reads as its own clear,
 * evenly-placed position regardless of how skewed the underlying numbers are -- the order between
 * them (which is real data) is preserved; the distance between them (which was never the point of
 * this bar) is not. Values outside `[axisLow, axisHigh]` are still clamped into that range first
 * (e.g. price already broke through resistance), so `axisLow`/`axisHigh` remain the guaranteed
 * leftmost/rightmost ranks no matter what the other values do.
 */
@Composable
fun PriceRangeBar(
    axisLow: Double,
    axisHigh: Double,
    valueAreaLow: Double,
    valueAreaHigh: Double,
    fairValueAnchor: Double,
    support: Double,
    resistance: Double,
    currentPrice: Double,
    modifier: Modifier = Modifier
) {
    val pulseColors = LocalPulseColors.current

    // 💡 Ranked (not dollar-proportional) x-positions -- see this file's doc comment above for why.
    // Every value is clamped into `[axisLow, axisHigh]` first so those two stay the guaranteed
    // leftmost/rightmost ranks, then the whole set is de-duplicated (two inputs that land on the
    // exact same value, e.g. `axisLow` and `valueAreaLow` sharing one field upstream, must render
    // at the exact same position, not get pushed apart into artificial neighboring ranks) and
    // sorted, so each distinct value's rank is just its index in that list.
    val rankedValues = listOf(
        axisLow,
        valueAreaLow.coerceIn(axisLow, axisHigh),
        fairValueAnchor.coerceIn(axisLow, axisHigh),
        valueAreaHigh.coerceIn(axisLow, axisHigh),
        support.coerceIn(axisLow, axisHigh),
        currentPrice.coerceIn(axisLow, axisHigh),
        resistance.coerceIn(axisLow, axisHigh),
        axisHigh
    ).distinct().sorted()
    val lastRank = (rankedValues.size - 1).coerceAtLeast(1)
    fun fractionOf(value: Double): Float =
        rankedValues.indexOf(value.coerceIn(axisLow, axisHigh)).toFloat() / lastRank

    // 💡 Both derived from this preset's own `accentPrimary` (the strong brand color), not the
    // same washed-out surface tokens the card background itself is built from -- track and value
    // area used to render at a contrast ratio of roughly 1.0-1.2 against the card in every preset
    // (measured, not eyeballed), meaning they were essentially the same color as what's behind
    // them. `accentPrimary` swaps between a dark, saturated tone (light presets) and a light,
    // bright one (dark presets) specifically so it reads clearly against its own preset's card
    // background either way; 20%/55% opacity keeps the track a subtle base and the value area a
    // clearly stronger, distinctly readable band above it, verified across all 10 presets.
    val trackColor = pulseColors.accentPrimary.copy(alpha = 0.20f)
    val valueAreaColor = pulseColors.accentPrimary.copy(alpha = 0.55f)
    val valueAreaBorderColor = pulseColors.accentPrimary
    val fairValueColor = MaterialTheme.colorScheme.onSurface
    // 💡 Support/resistance colored bullish-green/bearish-red -- a direction read (which side of
    // price is the floor vs. the ceiling), the same signal-color pairing this app uses everywhere
    // else for bullish/bearish, rather than a neutral tick color for both.
    val supportColor = pulseColors.signalBullishText
    val resistanceColor = pulseColors.signalBearishText
    val priceColor = pulseColors.accentPrimary
    // 💡 Axis-endpoint labels are onSurface, not onSurfaceMuted -- see the axisLow/axisHigh `Text`
    // calls below. Was muted, which on some presets rendered as little more than a faint grey
    // line, making a range bar whose whole purpose is showing where price sits relative to
    // support/resistance genuinely hard to read at a glance.
    val axisLabelColor = MaterialTheme.colorScheme.onSurface
    val priceLabelStyle = MaterialTheme.typography.labelSmall.copy(fontWeight = FontWeight.Bold, color = priceColor)
    // 💡 `dimensionResource`/`rememberTextMeasurer`/`MaterialTheme.typography` are only usable in
    // composition, not inside Canvas's `onDraw: DrawScope.() -> Unit` lambda below, which runs at
    // draw time -- resolved here instead, then read (and `.toPx()`'d, a plain `DrawScope`
    // extension safe to call from inside the lambda) from there.
    val tickWidthDp = dimensionResource(id = R.dimen.gauge_needle_width)
    val valueAreaBorderWidthDp = dimensionResource(id = R.dimen.border_thin)
    // 💡 The track is inset from both canvas edges by this much -- support/resistance (and the
    // value area they bound) used to sit flush against the track's own rounded end caps, which
    // read as clipped/half-hidden rather than as a distinct marker. Now every tick always lands
    // inside the visible track, never on its curved edge.
    val trackInsetDp = dimensionResource(id = R.dimen.padding_medium)
    // 💡 Canvas height is now two stacked regions: a label area on top (room for the current
    // price's own value label, replacing a bare unlabeled dot) and the original track area below
    // it (unchanged size/proportions from before -- the track, its ticks, and the price dot all
    // still work exactly as they did). `padding_xxlarge` rather than reusing `padding_xlarge`
    // again for the label area specifically because an 11sp label plus its connector line needs a
    // bit more room than the track's own height to avoid feeling cramped.
    val priceLabelAreaHeightDp = dimensionResource(id = R.dimen.padding_xxlarge)
    val trackAreaHeightDp = dimensionResource(id = R.dimen.padding_xlarge)
    val priceLabelGapDp = dimensionResource(id = R.dimen.padding_tiny)
    val textMeasurer = rememberTextMeasurer()

    Column(modifier = modifier.fillMaxWidth()) {
        Canvas(
            modifier = Modifier
                .fillMaxWidth()
                .height(priceLabelAreaHeightDp + trackAreaHeightDp)
        ) {
            val trackInset = trackInsetDp.toPx()
            val trackWidth = size.width - 2 * trackInset
            fun xOf(value: Double): Float = trackInset + fractionOf(value) * trackWidth

            val trackAreaTop = priceLabelAreaHeightDp.toPx()
            val trackAreaHeight = size.height - trackAreaTop
            val barHeight = trackAreaHeight * 0.4f
            val barTop = trackAreaTop + (trackAreaHeight - barHeight) / 2f

            drawRoundRect(
                color = trackColor,
                topLeft = Offset(trackInset, barTop),
                size = Size(trackWidth, barHeight),
                cornerRadius = CornerRadius(barHeight / 2, barHeight / 2)
            )

            val valueAreaStartX = xOf(valueAreaLow)
            val valueAreaEndX = xOf(valueAreaHigh)
            val valueAreaSize = Size(valueAreaEndX - valueAreaStartX, barHeight)
            val valueAreaCornerRadius = CornerRadius(barHeight / 2, barHeight / 2)
            drawRoundRect(
                color = valueAreaColor,
                topLeft = Offset(valueAreaStartX, barTop),
                size = valueAreaSize,
                cornerRadius = valueAreaCornerRadius
            )
            drawRoundRect(
                color = valueAreaBorderColor,
                topLeft = Offset(valueAreaStartX, barTop),
                size = valueAreaSize,
                cornerRadius = valueAreaCornerRadius,
                style = Stroke(width = valueAreaBorderWidthDp.toPx())
            )

            fun tick(value: Double, color: Color) {
                val x = xOf(value)
                drawLine(
                    color = color,
                    start = Offset(x, trackAreaTop),
                    end = Offset(x, size.height),
                    strokeWidth = tickWidthDp.toPx(),
                    cap = StrokeCap.Round
                )
            }
            tick(fairValueAnchor, fairValueColor)
            tick(support, supportColor)
            tick(resistance, resistanceColor)

            // 💡 Current price gets its own labeled marker (value label + connector + dot)
            // instead of a bare dot -- a floating dot with no label read as unreadable/ambiguous
            // next to the labeled support/resistance ticks. The label's x position is clamped so
            // it can't run off either edge of the canvas when price sits near `axisLow`/`axisHigh`.
            val priceX = xOf(currentPrice)
            val priceText = "$${String.format(Locale.US, "%.2f", currentPrice)}"
            val textLayoutResult = textMeasurer.measure(text = priceText, style = priceLabelStyle)
            val textTopLeftX = (priceX - textLayoutResult.size.width / 2f)
                .coerceIn(0f, size.width - textLayoutResult.size.width)
            drawText(textLayoutResult = textLayoutResult, topLeft = Offset(textTopLeftX, 0f))

            val dotRadius = trackAreaHeight / 2.2f
            val dotCenterY = trackAreaTop + trackAreaHeight / 2f
            val stemTopY = textLayoutResult.size.height + priceLabelGapDp.toPx()
            val stemBottomY = dotCenterY - dotRadius
            if (stemBottomY > stemTopY) {
                drawLine(
                    color = priceColor,
                    start = Offset(priceX, stemTopY),
                    end = Offset(priceX, stemBottomY),
                    strokeWidth = tickWidthDp.toPx() * 0.6f,
                    cap = StrokeCap.Round
                )
            }
            drawCircle(color = priceColor, radius = dotRadius, center = Offset(priceX, dotCenterY))
        }

        // 💡 Inset by the same `trackInsetDp` the track itself uses, so `$200`/`$275` line up
        // under the track's actual left/right edges instead of the full (wider) canvas width.
        Row(modifier = Modifier.fillMaxWidth().padding(horizontal = trackInsetDp)) {
            Text(
                text = "$${axisLow.roundToInt()}",
                style = MaterialTheme.typography.labelSmall,
                color = axisLabelColor
            )
            androidx.compose.foundation.layout.Spacer(modifier = Modifier.weight(1f))
            Text(
                text = "$${axisHigh.roundToInt()}",
                style = MaterialTheme.typography.labelSmall,
                color = axisLabelColor
            )
        }
    }
}

